     2046:             p = (uint32_t)TIFFReadFile(tif, &ob[sizeof(uint32_t) + 5], 64);
     2047:             if (p != 64)
     2048:             {
     2049:                 _TIFFfreeExt(tif, ob);
     2050:                 return (0);
     2051:             }
     2052:             if (sp->qtable[m] != 0)
     2053:                 _TIFFfreeExt(tif, sp->qtable[m]);
     2054:             sp->qtable[m] = ob;
     2055:             sp->sof_tq[m] = m;
     2056:         }
     2057:         else
     2058:             sp->sof_tq[m] = sp->sof_tq[m - 1];
